// SUNLIGHT API — Cloudflare Worker + D1 (binding name: DB). No secrets or env vars required.
const CORS = { 'access-control-allow-origin': '*', 'access-control-allow-headers': 'content-type, authorization', 'access-control-allow-methods': 'GET, POST, OPTIONS' };
const json = (d, s = 200) => new Response(JSON.stringify(d), { status: s, headers: { 'content-type': 'application/json', 'cache-control': 'no-store', ...CORS } });
const hex = b => [...new Uint8Array(b)].map(x => x.toString(16).padStart(2, '0')).join('');
const rand = n => hex(crypto.getRandomValues(new Uint8Array(n)));
const PAGE = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover, interactive-widget=resizes-content\">\n<meta name=\"theme-color\" content=\"#075B42\">\n<title>SUNLIGHT</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css\">\n<style>\n:root{\n  --green:#075B42; --green-d:#054733; --gold:#F5C542; --gold-s:rgba(245,197,66,.22);\n  --bg:#fff; --text:#17231F; --muted:#6B7A74; --line:#EAF0ED; --soft:#F4F8F6; --blue:#2F9BFF;\n  --shadow:0 6px 20px rgba(7,91,66,.16); --r:16px;\n}\n*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}\nhtml,body{height:100%;overflow-x:hidden}\nbody{font-family:'Inter',system-ui,sans-serif;background:#E9EFEC;color:var(--text);font-size:15px}\nbutton{font:inherit;color:inherit;background:none;border:0;cursor:pointer}\ninput{font:inherit;color:inherit;border:0;outline:0;background:none}\nul{list-style:none}\n:focus-visible{outline:2px solid var(--gold);outline-offset:2px}\n\n.app{position:relative;display:flex;flex-direction:column;height:100dvh;max-width:480px;margin:0 auto;background:var(--bg);overflow:hidden;box-shadow:0 0 40px rgba(0,0,0,.12)}\n\n/* header */\n.top{position:relative;background:var(--green);color:#fff;padding:calc(10px + env(safe-area-inset-top,0px)) 14px 10px;z-index:20}\n.top-row{display:flex;align-items:center;justify-content:space-between;height:42px}\n.brand{display:flex;align-items:center;gap:10px}\n.logo{width:34px;height:34px;border-radius:11px;background:#fff;display:grid;place-items:center;color:var(--gold);font-size:19px;box-shadow:0 2px 8px rgba(0,0,0,.18)}\n.logo i{animation:spin 24s linear infinite}\n@keyframes spin{to{transform:rotate(360deg)}}\n.brand h1{font-size:20px;font-weight:800;letter-spacing:.06em}\n.top-actions{display:flex;gap:2px}\n.icon-btn{width:40px;height:40px;border-radius:50%;display:grid;place-items:center;font-size:17px;color:inherit;transition:background .2s,transform .15s}\n.icon-btn:active{background:rgba(255,255,255,.16);transform:scale(.92)}\n.icon-btn.small{width:32px;height:32px;font-size:15px}\n.icon-btn.light{color:#fff}\n.searchbar{display:flex;align-items:center;gap:10px;background:#fff;color:var(--text);border-radius:14px;padding:0 6px 0 14px;height:0;opacity:0;overflow:hidden;margin-top:0;transition:height .25s,opacity .25s,margin .25s}\n.searchbar.open{height:44px;opacity:1;margin-top:10px}\n.searchbar i{color:var(--muted);font-size:14px}\n.searchbar input{flex:1;min-width:0}\n.searchbar .icon-btn{color:var(--muted)}\n.dropdown{position:absolute;right:12px;top:calc(54px + env(safe-area-inset-top,0px));width:210px;background:#fff;color:var(--text);border-radius:14px;padding:6px;box-shadow:0 12px 32px rgba(0,0,0,.22);opacity:0;transform:translateY(-8px) scale(.96);transform-origin:top right;pointer-events:none;transition:.18s}\n.dropdown.open{opacity:1;transform:none;pointer-events:auto}\n.dropdown li{display:flex;align-items:center;gap:12px;padding:12px;border-radius:10px;font-weight:500;cursor:pointer}\n.dropdown li i{width:18px;color:var(--green);text-align:center}\n.dropdown li:active,.dropdown li:hover{background:var(--soft)}\n\n/* main + views */\nmain{flex:1;overflow-y:auto;overflow-x:hidden;position:relative;padding-bottom:96px;scrollbar-width:none}\nmain::-webkit-scrollbar{display:none}\n.view{display:none}\n.view.active{display:block;animation:fade .28s ease}\n@keyframes fade{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}\n.title{font-size:24px;font-weight:800;padding:18px 16px 8px}\n.sub{font-size:13px;font-weight:600;color:var(--muted);padding:14px 16px 6px}\n\n/* tabs */\n.tabs{display:flex;gap:8px;padding:12px 14px 4px;overflow-x:auto;scrollbar-width:none}\n.tabs::-webkit-scrollbar{display:none}\n.tab{position:relative;padding:8px 16px;border-radius:20px;background:var(--soft);color:var(--muted);font-weight:600;font-size:14px;white-space:nowrap;display:flex;align-items:center;gap:6px;transition:.25s}\n.tab.active{background:var(--green);color:#fff}\n.tab.active::after{content:\"\";position:absolute;left:50%;bottom:-3px;width:18px;height:3px;border-radius:3px;background:var(--gold);transform:translateX(-50%)}\n.pill{background:var(--gold);color:var(--text);font-size:11px;font-weight:700;min-width:18px;height:18px;border-radius:9px;display:none;place-items:center;padding:0 5px}\n.pill.show{display:grid}\n\n/* stories */\n.stories{display:flex;gap:14px;padding:14px 14px 10px;overflow-x:auto;scrollbar-width:none}\n.stories::-webkit-scrollbar{display:none}\n.story{flex:0 0 64px;text-align:center;font-size:12px;font-weight:500}\n.story .avatar{margin:0 auto 6px}\n.story span.n{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.ring{border:2px solid var(--green);box-shadow:0 0 0 2px #fff,0 0 0 4px var(--gold);margin:4px}\n.ring.seen{border-color:#CBD6D1;box-shadow:0 0 0 2px #fff,0 0 0 4px #E3EAE7}\n.add-badge{position:absolute;right:-2px;bottom:-2px;width:22px;height:22px;border-radius:50%;background:var(--gold);color:var(--green-d);border:2px solid #fff;display:grid;place-items:center;font-size:10px}\n\n/* avatar */\n.avatar{position:relative;width:52px;height:52px;border-radius:50%;background:var(--green);color:#fff;display:grid;place-items:center;font-weight:700;font-size:18px;flex:none}\n.avatar img{position:absolute;inset:0;width:100%;height:100%;border-radius:50%;object-fit:cover}\n.avatar.sm{width:40px;height:40px;font-size:15px}\n.avatar.big{width:64px;height:64px;font-size:24px}\n.avatar .dot{position:absolute;right:0;bottom:1px;width:13px;height:13px;border-radius:50%;background:#2DCB73;border:2.5px solid #fff}\n\n/* rows */\n.row{display:flex;align-items:center;gap:13px;padding:11px 16px;cursor:pointer;transition:background .15s;animation:fade .3s ease both}\n.row:active{background:var(--soft)}\n.row .body{flex:1;min-width:0;border-bottom:1px solid var(--line);padding-bottom:11px;margin-bottom:-11px;padding-top:0}\n.row:last-child .body{border-bottom:0}\n.line{display:flex;justify-content:space-between;align-items:center;gap:8px}\n.line strong{font-weight:600;font-size:16px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.time{font-size:12px;color:var(--muted);flex:none}\n.time.new{color:var(--green);font-weight:600}\n.preview{color:var(--muted);font-size:14px;margin-top:3px;display:flex;align-items:center;gap:5px;min-width:0}\n.preview .txt{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.preview .grow{flex:1;min-width:0;display:flex;align-items:center;gap:5px}\n.tick{font-size:12px;color:#9AA8A2;flex:none}\n.tick.read{color:var(--blue)}\n.badge{background:var(--green);color:#fff;font-size:11px;font-weight:700;min-width:20px;height:20px;border-radius:10px;display:grid;place-items:center;padding:0 6px;flex:none}\n.fav-ico{color:var(--gold);font-size:12px}\n.missed strong,.missed .txt{color:#D64545}\n.call-btn{color:var(--green);font-size:17px;width:38px;height:38px;border-radius:50%;display:grid;place-items:center}\n.empty{text-align:center;color:var(--muted);padding:48px 24px}\n.empty i{font-size:30px;color:var(--gold);margin-bottom:12px;display:block}\n\n/* updates / settings */\n.my-status{display:flex;align-items:center;gap:13px;padding:8px 16px}\n.my-status p,.profile-card p{color:var(--muted);font-size:13px;margin-top:2px}\n.profile-card{display:flex;align-items:center;gap:14px;margin:6px 16px 10px;padding:16px;border-radius:var(--r);background:var(--soft)}\n.set-row{display:flex;align-items:center;gap:14px;padding:14px 16px;cursor:pointer}\n.set-row:active{background:var(--soft)}\n.set-ico{width:36px;height:36px;border-radius:11px;background:var(--gold-s);color:var(--green);display:grid;place-items:center;font-size:15px}\n.set-row small{display:block;color:var(--muted);font-size:12px;margin-top:2px}\n\n/* fab */\n.fab{position:absolute;right:18px;bottom:88px;width:58px;height:58px;border-radius:50%;background:var(--green);color:#fff;font-size:21px;display:grid;place-items:center;box-shadow:var(--shadow);border:3px solid var(--gold);z-index:15;transition:transform .2s,opacity .2s}\n.fab:active{transform:scale(.9)}\n.fab.hide{transform:scale(0);opacity:0;pointer-events:none}\n\n/* bottom nav */\n.bottom-nav{position:absolute;left:0;right:0;bottom:0;display:flex;background:#fff;border-top:1px solid var(--line);padding:8px 4px calc(8px + env(safe-area-inset-bottom,0px));box-shadow:0 -4px 18px rgba(23,35,31,.06);z-index:16}\n.nav-item{flex:1;display:flex;flex-direction:column;align-items:center;gap:4px;font-size:11px;font-weight:500;color:var(--muted);transition:color .2s}\n.nav-ico{width:52px;height:30px;border-radius:15px;display:grid;place-items:center;font-size:16px;transition:background .25s}\n.nav-item.active{color:var(--green);font-weight:700}\n.nav-item.active .nav-ico{background:var(--gold-s)}\n\n/* overlay screens */\n.screen{position:absolute;inset:0;background:#fff;z-index:30;display:flex;flex-direction:column;transform:translateX(100%);visibility:hidden;transition:transform .3s cubic-bezier(.3,.8,.3,1),visibility .3s}\n.screen.open{transform:none;visibility:visible}\n.screen-head{display:flex;align-items:center;gap:8px;background:var(--green);color:#fff;padding:calc(10px + env(safe-area-inset-top,0px)) 8px 10px 6px;min-height:62px}\n.screen-head strong{display:block;font-size:17px;font-weight:600}\n.screen-head small{display:block;font-size:12px;opacity:.8;margin-top:1px}\n.screen-head .grow{flex:1;min-width:0}\n.screen > .chat-list,.screen > .sub{flex:none}\n#newChat{overflow:hidden}\n.quick button{display:flex;align-items:center;gap:14px;width:100%;padding:12px 16px;font-weight:600;text-align:left}\n.quick button:active{background:var(--soft)}\n.q-ico{width:44px;height:44px;border-radius:50%;background:var(--gold);color:var(--green-d);display:grid;place-items:center}\n\n/* conversation */\n.chat-screen{background:#F3F1EA}\n.messages{flex:1;overflow-y:auto;padding:14px 12px;display:flex;flex-direction:column;gap:6px}\n.day{align-self:center;background:#fff;color:var(--muted);font-size:12px;font-weight:500;padding:5px 12px;border-radius:10px;margin-bottom:6px;box-shadow:0 1px 2px rgba(0,0,0,.06)}\n.msg{max-width:80%;padding:8px 12px 6px;border-radius:14px;font-size:15px;line-height:1.4;word-wrap:break-word;box-shadow:0 1px 2px rgba(0,0,0,.07);animation:pop .22s ease both}\n@keyframes pop{from{opacity:0;transform:scale(.94) translateY(6px)}to{opacity:1;transform:none}}\n.msg.in{align-self:flex-start;background:#fff;border-top-left-radius:4px}\n.msg.out{align-self:flex-end;background:#D5EBDD;border-top-right-radius:4px}\n.msg small{display:flex;justify-content:flex-end;align-items:center;gap:4px;font-size:11px;color:var(--muted);margin-top:2px}\n.typing{align-self:flex-start;background:#fff;border-radius:14px;padding:11px 14px;display:flex;gap:4px}\n.typing i{width:6px;height:6px;border-radius:50%;background:#9AA8A2;animation:bounce 1s infinite}\n.typing i:nth-child(2){animation-delay:.15s}.typing i:nth-child(3){animation-delay:.3s}\n@keyframes bounce{0%,60%,100%{transform:none}30%{transform:translateY(-4px)}}\n.composer{display:flex;align-items:center;gap:6px;padding:8px 8px calc(8px + env(safe-area-inset-bottom,0px));background:#fff;border-top:1px solid var(--line)}\n.composer .icon-btn{color:var(--muted)}\n.composer input{flex:1;min-width:0;background:var(--soft);border-radius:22px;padding:11px 16px}\n.send{width:44px;height:44px;border-radius:50%;background:var(--green);color:#fff;display:grid;place-items:center;font-size:16px;flex:none;transition:transform .15s}\n.send:active{transform:scale(.9)}\n\n/* new chat: search + contacts */\n.ns-wrap{flex:none;padding:12px 14px 8px;background:#fff;border-bottom:1px solid var(--line)}\n.ns-bar{display:flex;align-items:center;gap:10px;height:48px;padding:0 6px 0 15px;border-radius:16px;background:var(--soft);border:1.5px solid transparent;transition:border-color .2s,box-shadow .2s,background .2s}\n.ns-bar:focus-within{background:#fff;border-color:var(--gold);box-shadow:0 0 0 4px var(--gold-s)}\n.ns-bar>i{color:var(--green);font-size:14px}\n.ns-bar input{flex:1;min-width:0;height:100%;font-size:15px}\n.ns-bar input:focus-visible{outline:0}\n.ns-bar input::placeholder{color:#8E9C96}\n.ns-bar input::-webkit-search-cancel-button,.ns-bar input::-webkit-search-decoration{-webkit-appearance:none;display:none}\n.ns-spin{display:none;flex:none;width:16px;height:16px;border-radius:50%;border:2.5px solid var(--line);border-top-color:var(--green);animation:rot .7s linear infinite}\n.ns-bar.loading .ns-spin{display:block}\n.ns-clear{color:var(--muted)}\n.ns-body{flex:1;min-height:0;overflow-y:auto;padding-bottom:24px}\n.on{color:var(--green);font-weight:600}\nmark{background:var(--gold-s);color:inherit;border-radius:3px;padding:0 1px}\n.act-btn{flex:none;display:inline-flex;align-items:center;gap:6px;height:34px;padding:0 14px;border-radius:17px;font-size:13px;font-weight:700;transition:transform .15s,background .2s,color .2s}\n.act-btn:active{transform:scale(.94)}\n.act-btn:disabled{opacity:.7;cursor:default}\n.act-btn.add{background:var(--gold);color:var(--green-d);box-shadow:0 2px 8px var(--gold-s)}\n.act-btn.added{background:var(--soft);color:var(--green);opacity:1}\n.act-btn.rm{width:38px;height:38px;padding:0;justify-content:center;border-radius:50%;background:transparent;color:#9AA8A2;font-size:15px}\n.act-btn.rm:hover{background:var(--soft);color:#D64545}\n.act-btn.rm.armed{width:auto;height:34px;padding:0 12px;border-radius:17px;background:#FCE9E9;color:#D64545}\n.skel{display:flex;align-items:center;gap:13px;padding:11px 16px}\n.skel i{display:block;border-radius:8px;background:linear-gradient(90deg,var(--soft) 25%,#E4ECE8 37%,var(--soft) 63%);background-size:400% 100%;animation:shimmer 1.3s ease infinite}\n.skel .c{width:52px;height:52px;border-radius:50%;flex:none}\n.skel .l{height:13px}\n@keyframes shimmer{0%{background-position:100% 0}100%{background-position:0 0}}\n.empty small{display:block;margin-top:6px;font-size:13px}\n\n/* toast */\n.toast{position:absolute;left:50%;bottom:100px;transform:translate(-50%,20px);background:var(--text);color:#fff;padding:10px 18px;border-radius:22px;font-size:13px;font-weight:500;opacity:0;pointer-events:none;transition:.25s;z-index:60;white-space:nowrap;max-width:90%}\n.toast.show{opacity:1;transform:translate(-50%,0)}\n\n@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}\n\n/* auth */\n[hidden]{display:none!important}\n.auth{z-index:50;justify-content:center;align-items:center;padding:24px;background:#fff}\n.auth-card{width:100%;max-width:340px;display:flex;flex-direction:column;gap:12px;text-align:center}\n.logo.big{width:68px;height:68px;border-radius:22px;font-size:36px;background:var(--green);color:var(--gold);margin:0 auto 4px;box-shadow:var(--shadow)}\n.auth-card h2{font-size:26px;font-weight:800;letter-spacing:.06em;color:var(--green)}\n.auth-card p{color:var(--muted);font-size:14px;margin-bottom:6px}\n.auth-card label{display:block}\n.auth-card input{width:100%;background:var(--soft);border:1.5px solid transparent;border-radius:14px;padding:14px 16px;transition:border-color .2s}\n.auth-card input:focus{border-color:var(--gold)}\n.auth-err{color:#D64545!important;min-height:18px;margin:0!important;font-size:13px!important}\n.auth-btn{background:var(--green);color:#fff;font-weight:700;border-radius:14px;padding:14px;box-shadow:var(--shadow);transition:transform .15s}\n.auth-btn:active{transform:scale(.97)}\n.auth-btn:disabled{opacity:.6}\n.auth-switch{color:var(--green);font-weight:600;font-size:14px;padding:8px}\n\n.auth-btn{display:flex;align-items:center;justify-content:center;gap:10px}\n.auth-btn .spin{display:none;width:16px;height:16px;border-radius:50%;border:2.5px solid rgba(255,255,255,.35);border-top-color:var(--gold);animation:rot .7s linear infinite}\n.auth-btn.loading .spin{display:inline-block}\n@keyframes rot{to{transform:rotate(360deg)}}\n.auth-card input:disabled,.auth-switch:disabled{opacity:.6}\n</style>\n</head>\n<body>\n<div class=\"app\" id=\"app\">\n\n  <header class=\"top\">\n    <div class=\"top-row\">\n      <div class=\"brand\">\n        <span class=\"logo\"><i class=\"fa-solid fa-sun\"></i></span>\n        <h1>SUNLIGHT</h1>\n      </div>\n      <div class=\"top-actions\">\n        <button class=\"icon-btn\" id=\"cameraBtn\" aria-label=\"Camera\"><i class=\"fa-solid fa-camera\"></i></button>\n        <button class=\"icon-btn\" id=\"searchBtn\" aria-label=\"Search\"><i class=\"fa-solid fa-magnifying-glass\"></i></button>\n        <button class=\"icon-btn\" id=\"menuBtn\" aria-label=\"Menu\"><i class=\"fa-solid fa-ellipsis-vertical\"></i></button>\n      </div>\n    </div>\n    <div class=\"searchbar\" id=\"searchbar\">\n      <i class=\"fa-solid fa-magnifying-glass\"></i>\n      <input id=\"searchInput\" type=\"search\" placeholder=\"Search chats and messages\" autocomplete=\"off\">\n      <button class=\"icon-btn small\" id=\"searchClose\" aria-label=\"Close search\"><i class=\"fa-solid fa-xmark\"></i></button>\n    </div>\n    <ul class=\"dropdown\" id=\"menu\">\n      <li data-act=\"group\"><i class=\"fa-solid fa-user-group\"></i>New group</li>\n      <li data-act=\"star\"><i class=\"fa-regular fa-star\"></i>Starred messages</li>\n      <li data-act=\"devices\"><i class=\"fa-solid fa-laptop\"></i>Linked devices</li>\n      <li data-act=\"settings\"><i class=\"fa-solid fa-gear\"></i>Settings</li>\n    </ul>\n  </header>\n\n  <main id=\"main\">\n    <!-- CHATS -->\n    <section class=\"view active\" id=\"view-chats\">\n      <nav class=\"tabs\" id=\"tabs\">\n        <button class=\"tab active\" data-filter=\"all\">All</button>\n        <button class=\"tab\" data-filter=\"unread\">Unread<span class=\"pill\" id=\"unreadCount\"></span></button>\n        <button class=\"tab\" data-filter=\"fav\">Favorites</button>\n        <button class=\"tab\" data-filter=\"group\">Groups</button>\n      </nav>\n      <div class=\"stories\" id=\"stories\"></div>\n      <div class=\"chat-list\" id=\"chatList\"></div>\n    </section>\n\n    <!-- UPDATES -->\n    <section class=\"view\" id=\"view-updates\">\n      <h2 class=\"title\">Updates</h2>\n      <div class=\"my-status\" id=\"myStatus\"></div>\n      <h3 class=\"sub\">Recent updates</h3>\n      <div class=\"chat-list\" id=\"updateList\"></div>\n    </section>\n\n    <!-- COMMUNITIES -->\n    <section class=\"view\" id=\"view-communities\">\n      <h2 class=\"title\">Communities</h2>\n      <div class=\"chat-list\" id=\"communityList\"></div>\n    </section>\n\n    <!-- CALLS -->\n    <section class=\"view\" id=\"view-calls\">\n      <h2 class=\"title\">Calls</h2>\n      <div class=\"chat-list\" id=\"callList\"></div>\n    </section>\n\n    <!-- SETTINGS -->\n    <section class=\"view\" id=\"view-settings\">\n      <h2 class=\"title\">Settings</h2>\n      <div class=\"profile-card\" id=\"profileCard\"></div>\n      <div class=\"settings-list\" id=\"settingsList\"></div>\n    </section>\n  </main>\n\n  <button class=\"fab\" id=\"fab\" aria-label=\"New chat\"><i class=\"fa-solid fa-message\"></i></button>\n\n  <nav class=\"bottom-nav\" id=\"bottomNav\">\n    <button class=\"nav-item active\" data-view=\"chats\"><span class=\"nav-ico\"><i class=\"fa-solid fa-message\"></i></span>Chats</button>\n    <button class=\"nav-item\" data-view=\"updates\"><span class=\"nav-ico\"><i class=\"fa-regular fa-circle-dot\"></i></span>Updates</button>\n    <button class=\"nav-item\" data-view=\"communities\"><span class=\"nav-ico\"><i class=\"fa-solid fa-users\"></i></span>Communities</button>\n    <button class=\"nav-item\" data-view=\"calls\"><span class=\"nav-ico\"><i class=\"fa-solid fa-phone\"></i></span>Calls</button>\n    <button class=\"nav-item\" data-view=\"settings\"><span class=\"nav-ico\"><i class=\"fa-solid fa-gear\"></i></span>Settings</button>\n  </nav>\n\n  <!-- NEW CHAT -->\n  <div class=\"screen\" id=\"newChat\">\n    <div class=\"screen-head\">\n      <button class=\"icon-btn light\" data-close=\"newChat\" aria-label=\"Back\"><i class=\"fa-solid fa-arrow-left\"></i></button>\n      <div><strong>New chat</strong><small id=\"contactCount\"></small></div>\n    </div>\n    <div class=\"ns-wrap\">\n      <div class=\"ns-bar\" id=\"nsBar\" role=\"search\">\n        <i class=\"fa-solid fa-magnifying-glass\"></i>\n        <input id=\"nsInput\" type=\"search\" placeholder=\"Search by name or username\" autocomplete=\"off\" autocapitalize=\"none\" spellcheck=\"false\" maxlength=\"40\" aria-label=\"Search users\">\n        <span class=\"ns-spin\" aria-hidden=\"true\"></span>\n        <button type=\"button\" class=\"icon-btn small ns-clear\" id=\"nsClear\" aria-label=\"Clear search\" hidden><i class=\"fa-solid fa-xmark\"></i></button>\n      </div>\n    </div>\n    <div class=\"ns-body\" id=\"nsBody\">\n      <div id=\"nsHome\">\n        <div class=\"quick\">\n          <button data-act=\"group\"><span class=\"q-ico\"><i class=\"fa-solid fa-user-group\"></i></span>New group</button>\n          <button data-act=\"contact\"><span class=\"q-ico\"><i class=\"fa-solid fa-user-plus\"></i></span>New contact</button>\n          <button data-act=\"community\"><span class=\"q-ico\"><i class=\"fa-solid fa-users\"></i></span>New community</button>\n        </div>\n        <h3 class=\"sub\">My contacts</h3>\n        <div class=\"chat-list\" id=\"contactList\"></div>\n      </div>\n      <div id=\"nsResults\" hidden>\n        <h3 class=\"sub\" id=\"resTitle\">Search results</h3>\n        <div class=\"chat-list\" id=\"resultList\"></div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CONVERSATION -->\n  <div class=\"screen chat-screen\" id=\"chatScreen\">\n    <div class=\"screen-head\">\n      <button class=\"icon-btn light\" data-close=\"chatScreen\" aria-label=\"Back\"><i class=\"fa-solid fa-arrow-left\"></i></button>\n      <div class=\"avatar sm\" id=\"chatAvatar\"></div>\n      <div class=\"grow\"><strong id=\"chatName\"></strong><small id=\"chatState\"></small></div>\n      <button class=\"icon-btn light\" id=\"favBtn\" aria-label=\"Favorite\"><i class=\"fa-regular fa-star\"></i></button>\n      <button class=\"icon-btn light\" data-toast=\"Voice call\"><i class=\"fa-solid fa-phone\"></i></button>\n    </div>\n    <div class=\"messages\" id=\"messages\"></div>\n    <form class=\"composer\" id=\"composer\">\n      <button type=\"button\" class=\"icon-btn\" data-toast=\"Attachments\"><i class=\"fa-solid fa-paperclip\"></i></button>\n      <input id=\"msgInput\" type=\"text\" placeholder=\"Message\" autocomplete=\"off\">\n      <button class=\"send\" id=\"sendBtn\" aria-label=\"Send\"><i class=\"fa-solid fa-paper-plane\"></i></button>\n    </form>\n  </div>\n\n  <!-- AUTH -->\n  <div class=\"screen auth open\" id=\"auth\">\n    <form class=\"auth-card\" id=\"authForm\">\n      <span class=\"logo big\"><i class=\"fa-solid fa-sun\"></i></span>\n      <h2>SUNLIGHT</h2>\n      <p id=\"authSub\">Log in to continue</p>\n      <label hidden id=\"nameWrap\"><input id=\"authName\" type=\"text\" placeholder=\"Your name\" maxlength=\"40\" autocomplete=\"name\"></label>\n      <label hidden id=\"emailWrap\"><input id=\"authEmail\" type=\"email\" placeholder=\"Email (optional)\" maxlength=\"100\" autocomplete=\"email\"></label>\n      <label><input id=\"authUser\" type=\"text\" placeholder=\"Username or email\" maxlength=\"100\" autocomplete=\"username\" autocapitalize=\"none\" required></label>\n      <label><input id=\"authPass\" type=\"password\" placeholder=\"Password\" autocomplete=\"current-password\" required></label>\n      <p class=\"auth-err\" id=\"authErr\"></p>\n      <button class=\"auth-btn\" id=\"authBtn\"><span class=\"spin\" aria-hidden=\"true\"></span><span id=\"authBtnTxt\">Log in</span></button>\n      <button type=\"button\" class=\"auth-switch\" id=\"authSwitch\">New here? Create an account</button>\n    </form>\n  </div>\n\n  <div class=\"toast\" id=\"toast\"></div>\n</div>\n<script>\n'use strict';\nconst $ = (s, r = document) => r.querySelector(s);\nconst $$ = (s, r = document) => [...r.querySelectorAll(s)];\nconst esc = s => String(s).replace(/[&<>\"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\nconst COLORS = ['#075B42', '#0E7C5A', '#8A6D0B', '#2F6F8F', '#6B4E9B', '#B5533C'];\n\nlet token = localStorage.getItem('sl_token'), me = null, chats = [], contacts = [], results = [], current = null;\nlet filter = 'all', query = '', pollTimer = null, sigChats = '', sigContacts = '', sigMsgs = '';\nlet searchSeq = 0, searchTimer = null, lastQ = '';\nconst favs = new Set(JSON.parse(localStorage.getItem('sl_favs') || '[]'));\n\n/* ---------- API ---------- */\nasync function api(path, opts = {}) {\n  let res;\n  try {\n    res = await fetch((window.SUNLIGHT_API || '') + '/api/' + path, {\n      method: opts.body ? 'POST' : (opts.method || 'GET'),\n      headers: { 'content-type': 'application/json', ...(token ? { authorization: 'Bearer ' + token } : {}) },\n      body: opts.body ? JSON.stringify(opts.body) : undefined\n    });\n  } catch { throw new Error('Cannot reach the server. Check your internet connection.'); }\n  const data = await res.json().catch(() => null);\n  if (!data) throw new Error(`Unexpected server response (HTTP ${res.status}). Make sure the Worker is deployed.`);\n  if (res.status === 401 && token && path !== 'login' && path !== 'register') logout(true);\n  if (!res.ok) throw new Error(data.error || 'Something went wrong');\n  return data;\n}\n\n/* ---------- Helpers ---------- */\nconst initials = n => n.trim().split(/\\s+/).map(w => w[0]).slice(0, 2).join('').toUpperCase();\nconst avatar = (p, extra = '', dot = false) =>\n  `<div class=\"avatar ${extra}\" style=\"background:${COLORS[p.id % COLORS.length]}\"><span>${esc(initials(p.name))}</span>${dot && p.online ? '<i class=\"dot\"></i>' : ''}</div>`;\nconst tickIcon = t => t ? `<i class=\"fa-solid fa-check-double tick ${t === 'read' ? 'read' : ''}\"></i>` : '';\nconst clock = ts => new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false });\nfunction fmt(ts) {\n  const d = new Date(ts), n = new Date();\n  if (d.toDateString() === n.toDateString()) return clock(ts);\n  if (d.toDateString() === new Date(n - 864e5).toDateString()) return 'Yesterday';\n  return d.toLocaleDateString([], { day: 'numeric', month: 'short' });\n}\nlet toastTimer;\nfunction toast(text) {\n  const t = $('#toast');\n  t.textContent = text; t.classList.add('show');\n  clearTimeout(toastTimer);\n  toastTimer = setTimeout(() => t.classList.remove('show'), 1800);\n}\nconst openScreen = id => $('#' + id).classList.add('open');\nconst closeScreen = id => $('#' + id).classList.remove('open');\nconst empty = (icon, text) => `<div class=\"empty\"><i class=\"${icon}\"></i>${text}</div>`;\n\n/* ---------- Auth ---------- */\nlet mode = 'login';\nfunction setMode(m) {\n  mode = m;\n  $('#nameWrap').hidden = m === 'login';\n  $('#emailWrap').hidden = m === 'login';\n  $('#authUser').placeholder = m === 'login' ? 'Username or email' : 'Username';\n  $('#authSub').textContent = m === 'login' ? 'Log in to continue' : 'Create your SUNLIGHT account';\n  $('#authBtnTxt').textContent = m === 'login' ? 'Log in' : 'Create account';\n  $('#authSwitch').textContent = m === 'login' ? 'New here? Create an account' : 'Already have an account? Log in';\n  $('#authPass').autocomplete = m === 'login' ? 'current-password' : 'new-password';\n  $('#authErr').textContent = '';\n}\n$('#authSwitch').addEventListener('click', () => setMode(mode === 'login' ? 'register' : 'login'));\nlet busy = false;\nfunction setBusy(on) {\n  busy = on;\n  const b = $('#authBtn');\n  b.disabled = on; b.classList.toggle('loading', on); b.setAttribute('aria-busy', on);\n  $$('#authForm input').forEach(i => i.disabled = on);\n  $('#authSwitch').disabled = on;\n  $('#authBtnTxt').textContent = on ? (mode === 'login' ? 'Logging in\u2026' : 'Creating account\u2026') : (mode === 'login' ? 'Log in' : 'Create account');\n}\n$('#authForm').addEventListener('submit', async e => {\n  e.preventDefault();\n  if (busy) return;                                   // ignore repeated clicks while a request is running\n  const username = $('#authUser').value.trim(), password = $('#authPass').value;\n  const name = $('#authName').value.trim(), email = $('#authEmail').value.trim();\n  const err = $('#authErr'); err.textContent = '';\n  if (!username || !password) { err.textContent = 'Enter your username (or email) and password'; return; }\n  if (mode === 'register' && !name) { err.textContent = 'Enter your name'; return; }\n  setBusy(true);\n  try {\n    const d = await api(mode, { body: mode === 'login' ? { username, password } : { name, username, email, password } });\n    token = d.token; localStorage.setItem('sl_token', token);\n    $('#authPass').value = '';\n    await start(d.user);                              // closes the login screen and shows the Chats home\n  } catch (e2) { err.textContent = e2.message; }\n  setBusy(false);\n});\n\nfunction logout(silent) {\n  if (token && !silent) api('logout', { method: 'POST', body: {} }).catch(() => {});\n  token = null; me = null; current = null; chats = []; contacts = []; results = [];\n  localStorage.removeItem('sl_token');\n  clearInterval(pollTimer); sigChats = sigContacts = sigMsgs = ''; resetSearch();\n  ['chatScreen', 'newChat'].forEach(closeScreen);\n  openScreen('auth'); setMode('login');\n}\n\nasync function start(user) {\n  me = user;\n  closeScreen('auth');\n  renderProfile();\n  await Promise.all([loadChats(), loadContacts()]).catch(() => {});\n  showView('chats');\n  clearInterval(pollTimer);\n  pollTimer = setInterval(poll, 4000);\n}\n\n/* ---------- Data loading ---------- */\nasync function loadChats() {\n  const d = await api('chats');\n  const next = d.chats.map(c => ({\n    id: c.id, name: c.name, online: c.online, unread: c.unread, time: fmt(c.last_at), msg: c.last_body,\n    tick: c.last_sender === me.id ? (c.last_read ? 'read' : 'delivered') : null\n  }));\n  const sig = JSON.stringify(next);\n  chats = next;\n  if (sig !== sigChats) { sigChats = sig; renderChats(); }\n}\nasync function loadContacts() {\n  const d = await api('contacts');\n  const sig = JSON.stringify(d.contacts);\n  contacts = d.contacts;\n  if (sig !== sigContacts) { sigContacts = sig; renderStories(); renderLists(); syncResultFlags(); }\n}\nfunction poll() {\n  if (!me) return;\n  loadChats().catch(() => {}); loadContacts().catch(() => {});\n  if ($('#chatScreen').classList.contains('open')) loadMessages().catch(() => {});\n}\n\n/* ---------- Rendering ---------- */\nfunction renderChats() {\n  const q = query.trim().toLowerCase();\n  const list = chats.filter(c =>\n    (filter === 'all' || (filter === 'unread' && c.unread) || (filter === 'fav' && favs.has(c.id))) &&\n    (!q || c.name.toLowerCase().includes(q) || c.msg.toLowerCase().includes(q)));\n  $('#chatList').innerHTML = list.length ? list.map((c, i) => `\n    <div class=\"row\" data-id=\"${c.id}\" style=\"animation-delay:${Math.min(i, 8) * 30}ms\">\n      ${avatar(c, '', true)}\n      <div class=\"body\">\n        <div class=\"line\"><strong>${esc(c.name)}</strong><span class=\"time ${c.unread ? 'new' : ''}\">${esc(c.time)}</span></div>\n        <div class=\"preview\"><span class=\"grow\">${tickIcon(c.tick)}<span class=\"txt\">${esc(c.msg)}</span></span>\n          ${favs.has(c.id) && !c.unread ? '<i class=\"fa-solid fa-star fav-ico\"></i>' : ''}\n          ${c.unread ? `<span class=\"badge\">${c.unread}</span>` : ''}</div>\n      </div>\n    </div>`).join('')\n    : q ? empty('fa-regular fa-comment-dots', `No chats match \u201c${esc(query)}\u201d`)\n    : filter === 'group' ? empty('fa-solid fa-user-group', 'Groups are coming soon')\n    : filter === 'fav' ? empty('fa-regular fa-star', 'Open a chat and tap the star to add a favorite')\n    : filter === 'unread' ? empty('fa-solid fa-check-double', 'You\u2019re all caught up')\n    : empty('fa-regular fa-comment-dots', 'No chats yet.<br>Tap the green button to start one.');\n  const total = chats.filter(c => c.unread).length;\n  const pill = $('#unreadCount');\n  pill.textContent = total; pill.classList.toggle('show', total > 0);\n}\n\nfunction renderProfile() {\n  const mine = avatar(me, '');\n  $('#profileCard').innerHTML = `${mine.replace('class=\"avatar ', 'class=\"avatar big ')}<div><strong>${esc(me.name)}</strong><p>@${esc(me.username)}</p></div>`;\n  $('#myStatus').innerHTML = `${mine.replace('</div>', '<i class=\"add-badge fa-solid fa-plus\"></i></div>')}<div><strong>My status</strong><p>Tap to add a status update</p></div>`;\n  $('#settingsList').innerHTML = [\n    ['fa-key', 'Account', '@' + me.username, 'Account'],\n    ['fa-bell', 'Notifications', 'Message tones', 'Notifications'],\n    ['fa-circle-question', 'Help', 'Help centre, contact us', 'Help'],\n    ['fa-right-from-bracket', 'Log out', 'Sign out of this device', '__logout']\n  ].map(s => `<div class=\"set-row\" data-set=\"${s[3]}\"><span class=\"set-ico\"><i class=\"fa-solid ${s[0]}\"></i></span><div><strong>${s[1]}</strong><small>${esc(s[2])}</small></div></div>`).join('');\n}\n\nfunction renderStories() {\n  const mine = `<div class=\"story\" data-toast=\"Add status\"><div class=\"avatar\" style=\"background:${COLORS[me.id % COLORS.length]}\"><span>${esc(initials(me.name))}</span><i class=\"add-badge fa-solid fa-plus\"></i></div><span class=\"n\">My status</span></div>`;\n  $('#stories').innerHTML = mine + contacts.slice(0, 10).map(u =>\n    `<div class=\"story\" data-contact=\"${u.id}\">${avatar(u, `ring ${u.online ? '' : 'seen'}`)}<span class=\"n\">${esc(u.name.split(' ')[0])}</span></div>`).join('');\n}\n\nfunction renderLists() {\n  const rows = contacts.map(u => `\n    <div class=\"row\" data-open=\"${u.id}\">${avatar(u, '', true)}\n      <div class=\"body\"><div class=\"line\"><strong>${esc(u.name)}</strong></div>\n      <div class=\"preview\">${u.online ? '<span class=\"on\">Online</span>' : '@' + esc(u.username)}</div></div>\n      <button class=\"act-btn rm\" data-remove=\"${u.id}\" aria-label=\"Remove ${esc(u.name)} from contacts\"><i class=\"fa-solid fa-user-minus\"></i></button>\n    </div>`).join('');\n  $('#contactList').innerHTML = rows || empty('fa-solid fa-user-plus', 'No contacts yet.<small>Search above by name or username to add someone.</small>');\n  $('#updateList').innerHTML = contacts.length ? contacts.map(u => `\n    <div class=\"row\" data-toast=\"${esc(u.name)} has no new status\">${avatar(u, `ring ${u.online ? '' : 'seen'}`)}\n    <div class=\"body\"><div class=\"line\"><strong>${esc(u.name)}</strong></div><div class=\"preview\">No recent updates</div></div></div>`).join('')\n    : empty('fa-solid fa-user-plus', 'Add contacts to see their updates here.');\n  $('#contactCount').textContent = `${contacts.length} contact${contacts.length === 1 ? '' : 's'}`;\n}\n$('#communityList').innerHTML = empty('fa-solid fa-users', 'Communities are coming soon');\n$('#callList').innerHTML = empty('fa-solid fa-phone', 'Voice and video calls are coming soon');\n\n/* ---------- Navigation ---------- */\nfunction showView(name) {\n  $$('.view').forEach(v => v.classList.toggle('active', v.id === 'view-' + name));\n  $$('.nav-item').forEach(b => b.classList.toggle('active', b.dataset.view === name));\n  $('#fab').classList.toggle('hide', name !== 'chats');\n  $('#main').scrollTop = 0;\n  if (name !== 'chats') closeSearch();\n}\n$('#bottomNav').addEventListener('click', e => { const b = e.target.closest('.nav-item'); if (b) showView(b.dataset.view); });\n$('#tabs').addEventListener('click', e => {\n  const t = e.target.closest('.tab'); if (!t) return;\n  $$('.tab').forEach(x => x.classList.toggle('active', x === t));\n  filter = t.dataset.filter; renderChats();\n});\n\n/* ---------- Search ---------- */\nfunction closeSearch() {\n  $('#searchbar').classList.remove('open');\n  $('#searchInput').value = ''; query = ''; if (me) renderChats();\n}\n$('#searchBtn').addEventListener('click', () => {\n  showView('chats');\n  const bar = $('#searchbar');\n  if (bar.classList.contains('open')) return closeSearch();\n  bar.classList.add('open');\n  setTimeout(() => $('#searchInput').focus(), 250);\n});\n$('#searchClose').addEventListener('click', closeSearch);\n$('#searchInput').addEventListener('input', e => { query = e.target.value; renderChats(); });\n\n/* ---------- Menu ---------- */\nconst menu = $('#menu');\n$('#menuBtn').addEventListener('click', e => { e.stopPropagation(); menu.classList.toggle('open'); });\ndocument.addEventListener('click', e => { if (!menu.contains(e.target)) menu.classList.remove('open'); });\n$('#cameraBtn').addEventListener('click', () => toast('Camera is not available yet'));\n\nfunction action(act) {\n  menu.classList.remove('open');\n  if (act === 'settings') { closeScreen('newChat'); showView('settings'); }\n  else if (act === 'contact') { openScreen('newChat'); $('#nsInput').focus(); }\n  else toast({ group: 'Groups are coming soon', star: 'No starred messages yet', devices: 'No linked devices', contact: 'Contacts appear when friends join', community: 'Communities are coming soon' }[act] || act);\n}\n$$('[data-act]').forEach(el => el.addEventListener('click', () => action(el.dataset.act)));\n\ndocument.addEventListener('click', e => {\n  const t = e.target.closest('[data-toast]'); if (t) toast(t.dataset.toast);\n  const c = e.target.closest('[data-close]'); if (c) { closeScreen(c.dataset.close); if (c.dataset.close === 'newChat') resetSearch(); }\n  const s = e.target.closest('[data-set]');\n  if (s) s.dataset.set === '__logout' ? logout() : toast(s.dataset.set);\n});\n$('#fab').addEventListener('click', () => { resetSearch(); loadContacts().catch(() => {}); openScreen('newChat'); });\n\n/* ---------- Conversation ---------- */\nconst bubble = m => {\n  const out = m.sender_id === me.id;\n  return `<div class=\"msg ${out ? 'out' : 'in'}\">${esc(m.body)}<small>${clock(m.created_at)}${out ? tickIcon(m.read_at ? 'read' : 'delivered') : ''}</small></div>`;\n};\nconst scrollDown = () => { const m = $('#messages'); m.scrollTop = m.scrollHeight; };\nconst updateFav = () => { $('#favBtn i').className = (current && favs.has(current.id) ? 'fa-solid' : 'fa-regular') + ' fa-star'; };\n\nfunction openChat(id) {\n  const p = contacts.find(u => u.id === +id) || chats.find(c => c.id === +id) || results.find(u => u.id === +id); if (!p) return;\n  current = p; sigMsgs = '';\n  $('#chatAvatar').outerHTML = avatar(p, 'sm').replace('class=\"avatar sm\"', 'class=\"avatar sm\" id=\"chatAvatar\"');\n  $('#chatName').textContent = p.name;\n  $('#chatState').textContent = p.online ? 'online' : 'offline';\n  $('#messages').innerHTML = '';\n  updateFav(); openScreen('chatScreen'); closeScreen('newChat'); resetSearch();\n  loadMessages(true).then(loadChats).catch(err => toast(err.message));\n}\nasync function loadMessages(force) {\n  if (!current) return;\n  const who = current;\n  const d = await api('messages?with=' + who.id);\n  if (current !== who) return;\n  const sig = d.messages.map(m => m.id + (m.read_at ? 'r' : '')).join();\n  $('#chatState').textContent = d.online ? 'online' : 'offline';\n  if (!force && sig === sigMsgs) return;\n  sigMsgs = sig;\n  const box = $('#messages'), near = box.scrollHeight - box.scrollTop - box.clientHeight < 120;\n  let lastDay = '';\n  box.innerHTML = d.messages.length ? d.messages.map(m => {\n    const day = new Date(m.created_at).toDateString(); let h = '';\n    if (day !== lastDay) { lastDay = day; h = `<div class=\"day\">${day === new Date().toDateString() ? 'Today' : new Date(m.created_at).toLocaleDateString([], { day: 'numeric', month: 'short' })}</div>`; }\n    return h + bubble(m);\n  }).join('') : '<div class=\"day\">Say hello \ud83d\udc4b</div>';\n  if (force || near) scrollDown();\n}\n\n$('#chatList').addEventListener('click', e => { const r = e.target.closest('[data-id]'); if (r) openChat(r.dataset.id); });\ndocument.addEventListener('click', e => { const r = e.target.closest('[data-contact]'); if (r) openChat(r.dataset.contact); });\n$('#favBtn').addEventListener('click', () => {\n  if (!current) return;\n  favs.has(current.id) ? favs.delete(current.id) : favs.add(current.id);\n  localStorage.setItem('sl_favs', JSON.stringify([...favs]));\n  updateFav(); renderChats();\n  toast(favs.has(current.id) ? 'Added to favorites' : 'Removed from favorites');\n});\n$('#composer').addEventListener('submit', async e => {\n  e.preventDefault();\n  const input = $('#msgInput'), body = input.value.trim();\n  if (!body || !current) return;\n  input.value = '';\n  try {\n    await api('messages', { body: { to: current.id, body } });\n    await loadMessages(true); loadChats();\n  } catch (err) { toast(err.message); input.value = body; }\n});\n\n/* ---------- Search users & contacts ---------- */\nconst nsInput = $('#nsInput'), nsBar = $('#nsBar'), nsClear = $('#nsClear');\nconst showResults = on => { $('#nsHome').hidden = on; $('#nsResults').hidden = !on; $('#nsBody').scrollTop = 0; };\nconst hl = (text, q) => {                                   // highlight the matching part (safe: everything escaped)\n  const i = q ? text.toLowerCase().indexOf(q.toLowerCase()) : -1;\n  return i < 0 ? esc(text) : esc(text.slice(0, i)) + '<mark>' + esc(text.slice(i, i + q.length)) + '</mark>' + esc(text.slice(i + q.length));\n};\nconst skeleton = () => Array.from({ length: 5 }, (_, i) =>\n  `<div class=\"skel\"><i class=\"c\"></i><div style=\"flex:1\"><i class=\"l\" style=\"width:${50 - i * 4}%\"></i><i class=\"l\" style=\"width:${32 + i * 3}%;margin-top:9px\"></i></div></div>`).join('');\n\nfunction resultRow(u, q) {\n  const btn = u.is_contact\n    ? '<button class=\"act-btn added\" disabled><i class=\"fa-solid fa-check\"></i>Added</button>'\n    : `<button class=\"act-btn add\" data-add=\"${u.id}\"><i class=\"fa-solid fa-user-plus\"></i>Add</button>`;\n  return `<div class=\"row\" data-open=\"${u.id}\">${avatar(u, '', true)}\n    <div class=\"body\"><div class=\"line\"><strong>${hl(u.name, q)}</strong></div>\n    <div class=\"preview\"><span class=\"txt\">@${hl(u.username, q)}</span>${u.online ? '<span class=\"on\">\u00b7 Online</span>' : ''}</div></div>${btn}</div>`;\n}\nfunction renderResults() {\n  $('#resTitle').textContent = results.length ? `${results.length} ${results.length === 1 ? 'person' : 'people'} found` : 'Search results';\n  $('#resultList').innerHTML = results.length ? results.map(u => resultRow(u, lastQ)).join('')\n    : empty('fa-regular fa-face-frown', `No one found for \u201c${esc(lastQ)}\u201d<small>Check the spelling, or try their username.</small>`);\n}\nfunction syncResultFlags() {                                // keep Add/Added buttons in step with the contact list\n  if (!results.length) return;\n  const ids = new Set(contacts.map(c => c.id));\n  results.forEach(u => { u.is_contact = ids.has(u.id); });\n  if (!$('#nsResults').hidden) renderResults();\n}\nasync function runSearch(q) {\n  const seq = ++searchSeq;\n  nsBar.classList.add('loading');\n  try {\n    const d = await api('users/search?q=' + encodeURIComponent(q));\n    if (seq !== searchSeq) return;                          // a newer search replaced this one\n    results = d.users; lastQ = q; renderResults();\n  } catch (err) {\n    if (seq !== searchSeq) return;\n    results = [];\n    $('#resultList').innerHTML = empty('fa-solid fa-triangle-exclamation', esc(err.message));\n  }\n  nsBar.classList.remove('loading');\n}\nfunction resetSearch() {\n  clearTimeout(searchTimer); searchSeq++;\n  nsInput.value = ''; nsClear.hidden = true; nsBar.classList.remove('loading');\n  results = []; lastQ = ''; showResults(false);\n}\nnsInput.addEventListener('input', () => {\n  const q = nsInput.value.trim().replace(/^@+/, '');\n  nsClear.hidden = !nsInput.value;\n  clearTimeout(searchTimer);\n  if (!q) { searchSeq++; results = []; nsBar.classList.remove('loading'); showResults(false); return; }\n  if (!results.length) $('#resultList').innerHTML = skeleton();\n  showResults(true);\n  searchTimer = setTimeout(() => runSearch(q), 220);\n});\nnsInput.addEventListener('keydown', e => { if (e.key === 'Enter') nsInput.blur(); });\nnsClear.addEventListener('click', () => { resetSearch(); nsInput.focus(); });\n\nasync function addContact(id, btn) {\n  btn.disabled = true;\n  try {\n    const d = await api('contacts', { body: { user_id: id } });\n    const r = results.find(u => u.id === id); if (r) r.is_contact = true;\n    if (!$('#nsResults').hidden) renderResults();\n    toast(d.already ? 'Already in your contacts' : 'Added to contacts');\n    await loadContacts();\n  } catch (err) { toast(err.message); btn.disabled = false; }\n}\nasync function removeContact(id, btn) {\n  if (!btn.classList.contains('armed')) {                   // first tap arms, second tap confirms\n    btn.classList.add('armed'); btn.innerHTML = '<i class=\"fa-solid fa-trash\"></i>Remove';\n    setTimeout(() => { if (btn.isConnected) { btn.classList.remove('armed'); btn.innerHTML = '<i class=\"fa-solid fa-user-minus\"></i>'; } }, 3000);\n    return;\n  }\n  btn.disabled = true;\n  try {\n    await api('contacts/remove', { body: { user_id: id } });\n    toast('Removed from contacts');\n    await loadContacts();\n  } catch (err) { toast(err.message); btn.disabled = false; }\n}\n$('#newChat').addEventListener('click', e => {\n  const add = e.target.closest('[data-add]'); if (add) return addContact(+add.dataset.add, add);\n  const rm = e.target.closest('[data-remove]'); if (rm) return removeContact(+rm.dataset.remove, rm);\n  const row = e.target.closest('[data-open]'); if (row) openChat(row.dataset.open);\n});\n\n/* ---------- Init ---------- */\nsetMode('login');\nif (token) api('me').then(d => start(d.user)).catch(() => logout(true));\n</script>\n</body>\n</html>\n";
const ONLINE_MS = 30000, SESSION_MS = 30 * 864e5;
const EMAIL = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
const likeEsc = s => s.replace(/[\\%_]/g, '\\$&');            // escape LIKE wildcards in user input
const publicUser = (u, now) => ({ id: u.id, name: u.name, username: u.username, online: now - u.last_seen < ONLINE_MS }); // never includes email / hashes

async function hashPw(pw, salt) {
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(pw), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits({ name: 'PBKDF2', hash: 'SHA-256', salt: new TextEncoder().encode(salt), iterations: 100000 }, key, 256);
  return hex(bits);
}
const safeEq = (a, b) => { if (a.length !== b.length) return false; let r = 0; for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i); return r === 0; };

/* ---- schema: created / repaired automatically, so a missing table can never cause a 500 ---- */
const TABLES = [
  `CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, email TEXT, name TEXT NOT NULL, pass_hash TEXT NOT NULL, salt TEXT NOT NULL, created_at INTEGER NOT NULL, last_seen INTEGER NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id INTEGER NOT NULL, created_at INTEGER NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS messages (id INTEGER PRIMARY KEY AUTOINCREMENT, sender_id INTEGER NOT NULL, receiver_id INTEGER NOT NULL, body TEXT NOT NULL, created_at INTEGER NOT NULL, read_at INTEGER)`,
  `CREATE INDEX IF NOT EXISTS idx_msg_pair ON messages(sender_id, receiver_id, id)`,
  `CREATE INDEX IF NOT EXISTS idx_msg_recv ON messages(receiver_id, read_at)`,
  `CREATE TABLE IF NOT EXISTS contacts (owner_id INTEGER NOT NULL, contact_id INTEGER NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY (owner_id, contact_id))`,
  `CREATE INDEX IF NOT EXISTS idx_contacts_contact ON contacts(contact_id)`
];
const USER_COLS = { username: "TEXT", email: 'TEXT', name: "TEXT NOT NULL DEFAULT ''", pass_hash: "TEXT NOT NULL DEFAULT ''", salt: "TEXT NOT NULL DEFAULT ''", created_at: 'INTEGER NOT NULL DEFAULT 0', last_seen: 'INTEGER NOT NULL DEFAULT 0' };
let ready = null;
function ensureSchema(db) {
  ready ??= (async () => {
    for (const q of TABLES) await db.prepare(q).run();
    const have = (await db.prepare('PRAGMA table_info(users)').all()).results.map(c => c.name);
    for (const [col, type] of Object.entries(USER_COLS)) if (!have.includes(col)) await db.prepare(`ALTER TABLE users ADD COLUMN ${col} ${type}`).run();
    await db.prepare('CREATE UNIQUE INDEX IF NOT EXISTS idx_users_email ON users(email) WHERE email IS NOT NULL').run();
  })().catch(e => { ready = null; throw e; });
  return ready;
}

export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    if (!url.pathname.startsWith('/api/')) {
      // Page: prefer the static-assets binding (wrangler deploy); otherwise serve the page embedded in this file
      // (build.py fills PAGE), so a single worker.js pasted into the Cloudflare dashboard works with no extra binding.
      if (env.ASSETS) return env.ASSETS.fetch(req);
      if (PAGE && (req.method === 'GET' || req.method === 'HEAD'))
        return new Response(req.method === 'HEAD' ? null : PAGE, { headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-cache' } });
      return new Response('SUNLIGHT: no page is available. Use worker.single.js (page embedded), or deploy with wrangler so the "ASSETS" binding exists.', { status: 500, headers: { 'content-type': 'text/plain; charset=utf-8', 'cache-control': 'no-store' } });
    }
    if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers: CORS });
    if (!env.DB) return json({ error: 'Database is not connected. Add the D1 binding named "DB" in wrangler.toml and redeploy.', code: 'DB_BINDING' }, 500);
    try {
      await ensureSchema(env.DB);
      return await route(req, env, url);
    } catch (e) {
      const msg = String(e && e.message || e), ref = rand(3);
      console.error(`[SUNLIGHT ${ref}]`, msg);
      if (/no such table|no such column/i.test(msg)) return json({ error: 'Database tables are missing. Run: wrangler d1 execute DB --remote --file=schema.sql', code: 'DB_SCHEMA' }, 500);
      return json({ error: `Server error (ref ${ref}). Please try again.`, code: 'SERVER' }, 500);
    }
  }
};

async function startSession(db, user, now) {
  const token = rand(32);
  await db.prepare('INSERT INTO sessions(token,user_id,created_at) VALUES(?,?,?)').bind(token, user.id, now).run();
  return json({ token, user });
}

async function route(req, env, url) {
  const db = env.DB, p = url.pathname.slice(5), now = Date.now();
  const post = req.method === 'POST';
  const body = post ? await req.json().catch(() => ({})) : {};

  if (p === 'health') {
    const r = await db.prepare('SELECT COUNT(*) n FROM users').first();
    return json({ ok: true, database: 'connected', assets: !!env.ASSETS, users: r.n });
  }

  if (p === 'register' && post) {
    const username = String(body.username || '').trim().toLowerCase();
    const email = String(body.email || '').trim().toLowerCase();
    const name = String(body.name || '').trim();
    const pw = String(body.password || '');
    if (!/^[a-z0-9_]{3,20}$/.test(username)) return json({ error: 'Username: 3–20 letters, numbers or _' }, 400);
    if (email && !EMAIL.test(email)) return json({ error: 'Enter a valid email address' }, 400);
    if (!name || name.length > 40) return json({ error: 'Enter your name (max 40 characters)' }, 400);
    if (pw.length < 6) return json({ error: 'Password must be at least 6 characters' }, 400);
    const salt = rand(16);
    let r;
    try {
      r = await db.prepare('INSERT INTO users(username,email,name,pass_hash,salt,created_at,last_seen) VALUES(?,?,?,?,?,?,?)')
        .bind(username, email || null, name, await hashPw(pw, salt), salt, now, now).run();
    } catch (e) {
      if (/UNIQUE|constraint/i.test(String(e && e.message))) return json({ error: 'Username or email already taken' }, 409);
      throw e;
    }
    return startSession(db, { id: r.meta.last_row_id, username, name }, now);
  }

  if (p === 'login' && post) {
    const ident = String(body.username || body.email || body.identifier || '').trim().toLowerCase();
    const pw = String(body.password || '');
    if (!ident || !pw) return json({ error: 'Enter your username (or email) and password' }, 400);
    const u = await db.prepare('SELECT id,username,name,pass_hash,salt FROM users WHERE username=?1 OR email=?1').bind(ident).first();
    // same work + same message whether the account exists or not
    const ok = u && u.pass_hash && safeEq(await hashPw(pw, u.salt), u.pass_hash);
    if (!ok) return json({ error: 'Incorrect username/email or password' }, 401);
    return startSession(db, { id: u.id, username: u.username, name: u.name }, now);
  }

  // ---- authenticated routes ----
  const tok = (req.headers.get('authorization') || '').replace('Bearer ', '');
  const me = tok ? await db.prepare('SELECT u.id,u.username,u.name FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token=? AND s.created_at>?').bind(tok, now - SESSION_MS).first() : null;
  if (!me) return json({ error: 'Please log in' }, 401);
  await db.prepare('UPDATE users SET last_seen=? WHERE id=?').bind(now, me.id).run();

  if (p === 'me') return json({ user: me });

  if (p === 'logout' && post) {
    await db.prepare('DELETE FROM sessions WHERE token=?').bind(tok).run();
    return json({ ok: true });
  }

  // ---- search registered users by username or full name (authenticated only) ----
  if (p === 'users/search' && !post) {
    const q = (url.searchParams.get('q') || '').trim().replace(/^@+/, '').slice(0, 40);
    if (!q) return json({ users: [] });
    const ql = q.toLowerCase();
    const { results } = await db.prepare(`
      SELECT u.id,u.name,u.username,u.last_seen,
        EXISTS(SELECT 1 FROM contacts c WHERE c.owner_id=?1 AND c.contact_id=u.id) is_contact
      FROM users u
      WHERE u.id!=?1 AND (u.username LIKE ?2 ESCAPE '\\' OR u.name LIKE ?2 ESCAPE '\\')
      ORDER BY CASE WHEN u.username=?3 THEN 0 WHEN u.username LIKE ?4 ESCAPE '\\' THEN 1 WHEN u.name LIKE ?4 ESCAPE '\\' THEN 2 ELSE 3 END, u.name
      LIMIT 30`).bind(me.id, '%' + likeEsc(q) + '%', ql, likeEsc(q) + '%').all();
    return json({ users: results.map(u => ({ ...publicUser(u, now), is_contact: !!u.is_contact })) });
  }

  // ---- my saved contacts ----
  if (p === 'contacts' && !post) {
    const { results } = await db.prepare(
      'SELECT u.id,u.name,u.username,u.last_seen FROM contacts c JOIN users u ON u.id=c.contact_id WHERE c.owner_id=? ORDER BY u.name LIMIT 500'
    ).bind(me.id).all();
    return json({ contacts: results.map(u => publicUser(u, now)) });
  }

  if (p === 'contacts' && post) {
    const id = Number(body.user_id);
    if (!Number.isInteger(id) || id < 1) return json({ error: 'Invalid user' }, 400);
    if (id === me.id) return json({ error: 'You cannot add yourself as a contact' }, 400);
    const u = await db.prepare('SELECT id,name,username,last_seen FROM users WHERE id=?').bind(id).first();
    if (!u) return json({ error: 'User not found' }, 404);
    const r = await db.prepare('INSERT OR IGNORE INTO contacts(owner_id,contact_id,created_at) VALUES(?,?,?)').bind(me.id, id, now).run();
    return json({ contact: publicUser(u, now), already: !r.meta.changes });
  }

  if (p === 'contacts/remove' && post) {
    const id = Number(body.user_id);
    if (!Number.isInteger(id) || id < 1) return json({ error: 'Invalid user' }, 400);
    await db.prepare('DELETE FROM contacts WHERE owner_id=? AND contact_id=?').bind(me.id, id).run();
    return json({ ok: true });
  }

  if (p === 'chats') {
    const { results } = await db.prepare(`
      SELECT u.id,u.name,u.last_seen,m.body last_body,m.created_at last_at,m.sender_id last_sender,m.read_at last_read,
        (SELECT COUNT(*) FROM messages x WHERE x.sender_id=u.id AND x.receiver_id=?1 AND x.read_at IS NULL) unread
      FROM users u JOIN messages m ON m.id=(SELECT MAX(id) FROM messages WHERE (sender_id=?1 AND receiver_id=u.id) OR (sender_id=u.id AND receiver_id=?1))
      WHERE u.id!=?1 ORDER BY m.id DESC LIMIT 200`).bind(me.id).all();
    return json({ chats: results.map(c => ({ ...c, online: now - c.last_seen < ONLINE_MS, last_seen: undefined })) });
  }

  if (p === 'messages' && !post) {
    const peerId = parseInt(url.searchParams.get('with'), 10);
    if (!Number.isInteger(peerId)) return json({ error: 'User not found' }, 404);
    const peer = await db.prepare('SELECT id,last_seen FROM users WHERE id=?').bind(peerId).first();
    if (!peer) return json({ error: 'User not found' }, 404);
    await db.prepare('UPDATE messages SET read_at=? WHERE sender_id=? AND receiver_id=? AND read_at IS NULL').bind(now, peerId, me.id).run();
    const { results } = await db.prepare(`
      SELECT id,sender_id,body,created_at,read_at FROM (
        SELECT * FROM messages WHERE (sender_id=?1 AND receiver_id=?2) OR (sender_id=?2 AND receiver_id=?1) ORDER BY id DESC LIMIT 200
      ) ORDER BY id`).bind(me.id, peerId).all();
    return json({ messages: results, online: now - peer.last_seen < ONLINE_MS });
  }

  if (p === 'messages' && post) {
    const to = parseInt(body.to, 10), text = String(body.body || '').trim();
    if (!text || text.length > 2000) return json({ error: 'Message must be 1–2000 characters' }, 400);
    if (!Number.isInteger(to) || to === me.id || !(await db.prepare('SELECT id FROM users WHERE id=?').bind(to).first())) return json({ error: 'User not found' }, 404);
    const r = await db.prepare('INSERT INTO messages(sender_id,receiver_id,body,created_at) VALUES(?,?,?,?)').bind(me.id, to, text, now).run();
    return json({ id: r.meta.last_row_id });
  }

  return json({ error: 'Not found' }, 404);
}
